from itertools import chain, repeat
from typing import Any, Iterable, List

def ncycles(iterable: Iterable[Any], n: int) -> List[Any]:
    """Returns the sequence elements *n* times.

    iterable: an iterable sequence of elements to be repeated
    n: the number of times to repeat the elements of the iterable
    Example: ncycles(["a", "b"], 3) -> ['a', 'b', 'a', 'b', 'a', 'b']

    """
    if not isinstance(n, int):
        raise ValueError("n must be an integer")
    if n < 0:
        return []
    return list(chain.from_iterable(repeat(tuple(iterable), n)))
